mapper.sql:
u.tenant_id = #{tenantId}
AND u.department_id IN
#{id}

    AND (u.name ILIKE concat('%', #{keyword}, '%') OR u.username ILIKE concat('%', #{keyword}, '%'))


    AND u.status = #{status}

mapper.select:
SELECT 

WHERE u.tenant_id = #{tenantId} AND u.id = #{userId}
FOR UPDATE OF u

SELECT EXISTS(
    SELECT 1 FROM chengke_crm.sys_user
    WHERE tenant_id = #{tenantId} AND mobile = #{mobile}
      AND (#{excludeUserId,jdbcType=OTHER} IS NULL OR id <> #{excludeUserId,jdbcType=OTHER})
)

SELECT c.ancestor_id AS nodeId, count(u.id)::integer AS userCount
FROM chengke_crm.department_closure c
JOIN chengke_crm.sys_user u
  ON u.tenant_id = c.tenant_id AND u.department_id = c.descendant_id
WHERE c.tenant_id = #{tenantId}
  AND c.ancestor_id IN
  #{id}

      AND u.department_id IN
      #{id}

GROUP BY c.ancestor_id

SELECT id, parent_id AS parentId, name, node_type AS nodeType, status, depth FROM chengke_crm.department WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND status = 'active'
AND id IN #{id}
ORDER BY path_ids, sort_order, created_at, id

SELECT id, name, code, status, built_in AS builtIn
FROM chengke_crm.sys_role
WHERE tenant_id = #{tenantId} AND id = #{roleId}

SELECT department_id
FROM chengke_crm.sys_user
WHERE tenant_id = #{tenantId} AND id = #{userId}

SELECT EXISTS(
    SELECT 1
    FROM chengke_crm.department_closure c
    JOIN chengke_crm.department d
      ON d.tenant_id = c.tenant_id AND d.id = c.descendant_id AND d.deleted_at IS NULL
    WHERE c.tenant_id = #{tenantId}
      AND c.ancestor_id = #{departmentId}
      AND c.distance > 0
      AND c.descendant_id IN
      #{id}
)
